// @FIGURE_CODE_BEGIN
var W = 900, H = 600;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);
var scene = draw.group();

var COL = { black: '#141414', orange: '#cf7a4d', orangeTxt: '#c06a3c', gray: '#8a8a8a', teal: '#7fd4c1', nodeFill: '#ffffff' };
var R = 32, AH = 12, AW = 6;

// fixed node positions
var X = 130, XY = 300;          // input x
var HX = 460;                    // hidden column x
var YX = 810, YY = 300;          // output y
var BHX = 130, BHY = 110;        // bias node feeding hidden layer
var BYX = 620, BYY = 80;         // bias node feeding output

// state
var N = 3, labeled = false, focus = null;

function hiddenY(i) {
  var CY = 300;
  var sp = N > 1 ? Math.min(110, 420 / (N - 1)) : 0;
  return CY + (i - (N - 1) / 2) * sp;
}

function arrow(g, x1, y1, x2, y2, color, width, op) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var sx = x1 + ux * R, sy = y1 + uy * R;
  var tipX = x2 - ux * R, tipY = y2 - uy * R;
  var bx = tipX - ux * AH, by = tipY - uy * AH;
  var px = -uy, py = ux;
  var grp = g.group().opacity(op == null ? 1 : op);
  grp.line(sx, sy, bx, by).stroke({ color: color, width: width, linecap: 'round' });
  grp.polygon([
    [tipX, tipY],
    [bx + px * AW, by + py * AW],
    [bx - px * AW, by - py * AW]
  ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
  return grp;
}

function node(g, cx, cy, stroke, sw) {
  return g.circle(R * 2).center(cx, cy).fill(COL.nodeFill).stroke({ color: stroke, width: sw || 2 });
}

function label(g, x, y, base, sub, color, size, op) {
  var t = g.text(function (add) {
    add.tspan(base).font({ size: size || 20 });
    if (sub != null && sub !== '') add.tspan(String(sub)).font({ size: (size || 20) * 0.62 }).dy((size || 20) * 0.32);
  }).font({ family: 'Georgia, "Times New Roman", serif', style: 'italic', anchor: 'middle' })
    .fill(color).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  t.center(x, y);
  if (op != null) t.opacity(op);
  return t;
}

function edgeLabelPos(x1, y1, x2, y2, t, off) {
  var mx = x1 + (x2 - x1) * t, my = y1 + (y2 - y1) * t;
  var dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx * dx + dy * dy) || 1;
  var px = -dy / len, py = dx / len;
  return [mx + px * off, my + py * off];
}

function redraw() {
  scene.clear();
  var showBias = labeled || focus != null;
  var showLabels = labeled || focus != null;

  // panel caption
  scene.text(labeled ? 'a)' : 'b)').font({ family: 'Georgia, serif', size: 26, anchor: 'start' }).fill('#222').move(18, 22);

  function opFor(owner) { return focus == null ? 1 : (owner === focus ? 1 : 0.12); }
  function labShow(owner) { return showLabels && (focus == null || owner === focus); }

  // bias node -> output (phi_0)
  if (showBias) {
    arrow(scene, BYX, BYY, YX, YY, COL.orange, 2.2, opFor(-1));
    var p0 = edgeLabelPos(BYX, BYY, YX, YY, 0.42, -16);
    if (labShow(-1)) label(scene, p0[0], p0[1], 'φ', '0', COL.orangeTxt, 20, opFor(-1));
  }

  for (var i = 0; i < N; i++) {
    var hy = hiddenY(i);
    var op = opFor(i);

    // x -> h_i  (theta_i1)
    arrow(scene, X, XY, HX, hy, COL.black, 2.2, op);
    var pA = edgeLabelPos(X, XY, HX, hy, 0.42, -16);
    if (labShow(i)) label(scene, pA[0], pA[1], 'θ', (i + 1) + '1', COL.gray, 19, op);

    // biasH -> h_i  (theta_i0)
    if (showBias) {
      arrow(scene, BHX, BHY, HX, hy, COL.orange, 2.2, op);
      var pB = edgeLabelPos(BHX, BHY, HX, hy, 0.5, 16);
      if (labShow(i)) label(scene, pB[0], pB[1], 'θ', (i + 1) + '0', COL.orangeTxt, 19, op);
    }

    // h_i -> y  (phi_i)
    arrow(scene, HX, hy, YX, YY, COL.black, 2.2, op);
    var pC = edgeLabelPos(HX, hy, YX, YY, 0.5, -16);
    if (labShow(i)) label(scene, pC[0], pC[1], 'φ', (i + 1), COL.gray, 19, op);
  }

  // bias nodes
  if (showBias) {
    var bop = focus == null ? 1 : 0.5;
    node(scene, BHX, BHY, COL.orange, 2).opacity(bop);
    label(scene, BHX, BHY, '1', '', COL.orangeTxt, 22, bop);
    node(scene, BYX, BYY, COL.orange, 2).opacity(bop);
    label(scene, BYX, BYY, '1', '', COL.orangeTxt, 22, bop);
  }

  // input & output nodes
  node(scene, X, XY, COL.black, 2);
  label(scene, X, XY, 'x', '', '#111', 26);
  node(scene, YX, YY, COL.black, 2);
  label(scene, YX, YY, 'y', '', '#111', 26);

  // hidden nodes (drawn last, on top) with teal activation tick
  for (var j = 0; j < N; j++) {
    var hy2 = hiddenY(j);
    var isFoc = focus === j;
    var c = node(scene, HX, hy2, isFoc ? COL.orange : COL.black, isFoc ? 3.2 : 2);
    c.opacity(focus == null ? 1 : (isFoc ? 1 : 0.35));
    scene.line(HX - 9, hy2 + 9, HX + 12, hy2 - 12).stroke({ color: COL.teal, width: 4, linecap: 'round' })
      .opacity(focus == null ? 1 : (isFoc ? 1 : 0.35));
    label(scene, HX, hy2, 'h', (j + 1), '#111', 22, focus == null ? 1 : (isFoc ? 1 : 0.35));

    (function (idx, circ) {
      circ.css('cursor', 'pointer');
      circ.on('click', function () { focus = (focus === idx ? null : idx); redraw(); });
      circ.on('mousemove', function (e) {
        showTooltip('Hidden unit h_' + (idx + 1) + ' — click to isolate its θ_' + (idx + 1) + '1, θ_' + (idx + 1) + '0 and φ_' + (idx + 1), e);
      });
      circ.on('mouseleave', hideTooltip);
    })(j, c);
  }
}

// ---- interactions ----
function toggle_viewToggle(on) { labeled = on; redraw(); }
function update_hiddenUnits(v) { N = v; focus = null; redraw(); }
function trigger_clearFocus() { focus = null; redraw(); }

// ---- demo step player ----
var steps = [
  { title: 'Signal flow at a glance',
    narration: 'In the clean view the network reads left to right: one input x fans out to the hidden units h₁..h₃, and their activations fan in to the single output y. No numbers yet — just the architecture.',
    view: false, units: 3, focus: null },
  { title: 'Name every parameter',
    narration: 'Switch to the labeled view: orange bias nodes (1) and the θ / φ labels appear. The θ weights (with θ_i0 biases) govern the input-to-hidden linear map, and the φ weights (with φ_0 bias) govern the hidden-to-output combination.',
    view: true, units: 3, focus: null },
  { title: 'Trace one hidden unit',
    narration: 'Click h₂ to highlight only its owned parameters — incoming θ₂₁ from x, bias θ₂₀, and outgoing φ₂ to y — each hidden unit contributes one column of θ-weights and one φ-weight.',
    view: true, units: 3, focus: 1 },
